list_transactions.code:
const response = await client.transactions.listTransactions({limit: 50, offset: 0});
for (const transaction of response.map.transactions) {
    console.log(transaction.transaction_no, transaction.total_records);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

get_transaction.code:
const response = await client.transactions.getTransaction('IMPORT-2026-0001');
console.log(response.map.transaction_no, response.map.total_records);
for (const row of response.map.by_type) {
    console.log(row.type, row.count);
}

list_transaction_items.code:
const response = await client.transactions.listTransactionItems('IMPORT-2026-0001', {
    type: 'product',
    limit: 20,
    offset: 0,
    detail: 'slim',
});
for (const item of response.map.items) {
    console.log(item.id, item.name, item.sku);
}
console.log(response.map.pagination.total);
